+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every consume movement, and the
+ * difference (actual - theoretical). Items with neither above zero are left out.
+ */
+export function varianceReport(store, from, to) {
+  const round = (n) => Math.round(n * 1000) / 1000;
+  const theoretical = new Map();
+  const actual = new Map();
+  for (const sale of store.data.sales ?? []) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    const dish = store.data.dishes.find((d) => d.id === sale.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, sale.qty)) theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const ids = new Set([...theoretical.keys(), ...actual.keys()]);
+  return [...ids]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = round(theoretical.get(itemId) ?? 0);
+      const a = round(actual.get(itemId) ?? 0);
+      return { itemId, theoretical: t, actual: a, difference: round(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
